CREATE TABLE official_resource_policy(url text PRIMARY KEY,source_id text NOT NULL REFERENCES source_registry(id),purpose text NOT NULL,max_bytes integer NOT NULL CHECK(max_bytes BETWEEN 1024 AND 8388608),access_allowed boolean NOT NULL DEFAULT false,storage_allowed boolean NOT NULL DEFAULT false,display_allowed boolean NOT NULL DEFAULT false,terms_url text NOT NULL,review_basis text,reviewed_at timestamptz);
