CREATE TABLE official_resource_response(id uuid PRIMARY KEY,url text NOT NULL REFERENCES official_resource_policy(url),method text NOT NULL CHECK(method IN('GET','POST')),requested_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),request_info jsonb NOT NULL,http_status integer,headers jsonb NOT NULL,raw_content bytea,sha256 char(64),network jsonb NOT NULL,error text,CHECK(raw_content IS NULL OR sha256=encode(sha256(raw_content),'hex')));
CREATE INDEX official_resource_recent ON official_resource_response(url,requested_at DESC);
CREATE TRIGGER official_resource_immutable BEFORE UPDATE OR DELETE ON official_resource_response FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
CREATE TABLE official_release_calendar(id uuid PRIMARY KEY,source_id text NOT NULL REFERENCES source_registry(id),official_title text NOT NULL,title_zh text NOT NULL,planned_date date NOT NULL,planned_at timestamptz,source_timezone text NOT NULL,source_url text NOT NULL REFERENCES official_resource_policy(url),response_id uuid NOT NULL REFERENCES official_resource_response(id),excerpt text NOT NULL,version integer NOT NULL,content_hash char(64) NOT NULL,collected_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(source_url,official_title,planned_date,version));
CREATE TRIGGER official_calendar_immutable BEFORE UPDATE OR DELETE ON official_release_calendar FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
CREATE TABLE financial_brief(id uuid PRIMARY KEY,owner_key char(64) NOT NULL,coverage_start timestamptz NOT NULL,coverage_end timestamptz NOT NULL,queried_at timestamptz NOT NULL,source_filter text NOT NULL,topic_filter text NOT NULL,watch_only boolean NOT NULL,rule_version text NOT NULL,ai_version text,snapshot_id uuid NOT NULL UNIQUE,input_hash char(64) NOT NULL,report jsonb NOT NULL,inputs jsonb NOT NULL,status text NOT NULL CHECK(status IN('RULE_GENERATED','NO_MATCHING_DATA')),CHECK(coverage_end>coverage_start),CHECK(coverage_end<=queried_at));
CREATE INDEX financial_brief_owner_date ON financial_brief(owner_key,coverage_start DESC,queried_at DESC);
CREATE TRIGGER financial_brief_immutable BEFORE UPDATE OR DELETE ON financial_brief FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
CREATE TABLE sec_xbrl_fact(id uuid PRIMARY KEY,cik varchar(10) NOT NULL CHECK(cik~'^[0-9]{10}$'),taxonomy text NOT NULL,concept text NOT NULL,unit text NOT NULL,period_start date,period_end date NOT NULL,value numeric NOT NULL,accession text NOT NULL,form text NOT NULL CHECK(form IN('8-K','10-Q','10-K','8-K/A','10-Q/A','10-K/A')),filed_on date NOT NULL,fy integer,fp text,frame text,evidence_id uuid NOT NULL REFERENCES raw_evidence(id),version integer NOT NULL,raw_item jsonb NOT NULL,UNIQUE(cik,taxonomy,concept,unit,period_end,accession,version),CHECK(period_start IS NULL OR period_end>=period_start));
CREATE TRIGGER sec_xbrl_immutable BEFORE UPDATE OR DELETE ON sec_xbrl_fact FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
